+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.Arrays;
+import java.util.EnumSet;
+import java.util.Locale;
+import java.util.Set;
+
+/**
+ * Filter applied by the backend: free-text name terms and a set of statuses.
+ *
+ * @param name     whitespace-separated terms, each of which must occur in first or last name
+ * @param statuses accepted statuses; empty means every status
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    public static final CustomerFilter NONE = new CustomerFilter("", Set.of());
+
+    public CustomerFilter {
+        name = name == null ? "" : name.strip();
+        statuses = (statuses == null || statuses.isEmpty())
+                ? Set.of() : Set.copyOf(EnumSet.copyOf(statuses));
+    }
+
+    public boolean isEmpty() {
+        return name.isEmpty() && statuses.isEmpty();
+    }
+
+    public boolean matches(Customer customer) {
+        if (!statuses.isEmpty() && !statuses.contains(customer.status())) {
+            return false;
+        }
+        if (name.isEmpty()) {
+            return true;
+        }
+        String first = normalize(customer.firstName());
+        String last = normalize(customer.lastName());
+        return Arrays.stream(normalize(name).split("\\s+"))
+                .filter(term -> !term.isEmpty())
+                .allMatch(term -> first.contains(term) || last.contains(term));
+    }
+
+    static String normalize(String text) {
+        return Normalizer.normalize(text, Normalizer.Form.NFD)
+                .replaceAll("\\p{M}+", "")
+                .toLowerCase(Locale.ROOT);
+    }
+}
